#[test]
fn rocket_too_heavy_never_lifts_off() {
    let rocket = dragless_rocket(10.0);
    let r = simulate_vertical(&rocket, &c6(), &Environment::default(), &SimConfig::default());
    assert!(r.event(EventKind::Liftoff).is_none());
    assert!(r.apogee_m <= 1e-9);
