const near = (label, actual, expected, tol=1e-12) => {
  if (Math.abs(actual-expected) > tol) throw new Error(`${label}: ${actual} != ${expected}`);
  process.stdout.write(`PASS ${label}: ${actual}\n`);
};
const g=f.geometry, c=Object.fromEntries(f.components.map(x=>[x.id,x]));
const R=g.nose.base_radius_m, L=g.nose.length_m, M=f.reference_condition.mach;
const Aref=Math.PI*R*R;
near('reference area', Aref, f.reference_condition.reference_area_m2);
const beta=Math.sqrt(1-M*M);
near('beta', beta, f.reference_condition.compressibility_beta);
const rho=(L*L+R*R)/(2*R), a=rho-R;
const integral=(rho*rho+a*a)*L-L**3/3-a*(L*a+rho*rho*Math.asin(L/rho));
const volume=Math.PI*integral;
near('ogive volume', volume, g.nose.volume_m3);
const noseCp=L-volume/Aref;
near('nose CP', noseCp, c.nose_cone.cp_x_from_nose_m);
near('nose moment', c.nose_cone.cn_alpha_per_rad*noseCp, c.nose_cone.normal_force_moment_m_per_rad);
const fin=g.fin_set, s=fin.span_m, Cr=fin.root_chord_m, Ct=fin.tip_chord_m, Xt=fin.tip_leading_edge_sweep_m;
const Afin=s*(Cr+Ct)/2;
near('one-fin area', Afin, fin.one_fin_planform_area_m2);
const cosGamma=s/Math.sqrt(s*s+(Xt+(Ct-Cr)/2)**2);
near('midchord cos', cosGamma, fin.midchord_sweep_cos);
const ratio=beta*s*s/(Afin*cosGamma);
const one=2*Math.PI*(s*s/Aref)/(1+Math.sqrt(1+ratio*ratio));
near('one-fin CNalpha', one, c.fin_set.one_fin_cn_alpha_per_rad);
const projected=(fin.count/2)*one*fin.fin_fin_interference_multiplier;
near('projected fin CNalpha', projected, c.fin_set.count_projected_cn_alpha_per_rad);
const K=1+R/(s+R);
near('body interference factor', K, fin.body_interference_factor);
const finCn=K*projected;
near('fin-set CNalpha', finCn, c.fin_set.cn_alpha_per_rad);
const finLocal=Xt/3*(Cr+2*Ct)/(Cr+Ct)+(Cr*Cr+Ct*Ct+Cr*Ct)/(6*(Cr+Ct));
near('fin local CP', finLocal, c.fin_set.cp_x_from_fin_root_leading_edge_m);
const finGlobal=fin.root_leading_edge_x_m+finLocal;
near('fin global CP', finGlobal, c.fin_set.cp_x_from_nose_m);
near('fin moment', finCn*finGlobal, c.fin_set.normal_force_moment_m_per_rad);
const totalCn=c.nose_cone.cn_alpha_per_rad+c.body_tube.cn_alpha_per_rad+finCn;
near('total CNalpha', totalCn, f.totals.cn_alpha_per_rad);
const totalMoment=c.nose_cone.normal_force_moment_m_per_rad+c.body_tube.normal_force_moment_m_per_rad+c.fin_set.normal_force_moment_m_per_rad;
near('total moment', totalMoment, f.totals.normal_force_moment_m_per_rad);
const cp=totalMoment/totalCn;
near('total CP', cp, f.totals.cp_x_from_nose_m);
const mp=f.mass_properties_loaded_c6, dry=mp.dry_structure, motor=mp.motor;
near('dry first moment', dry.mass_kg*dry.cg_x_from_nose_m, dry.first_moment_kg_m);
near('motor first moment', motor.loaded_mass_kg*motor.cg_x_from_nose_m, motor.first_moment_kg_m);
const loaded=dry.mass_kg+motor.loaded_mass_kg;
near('loaded mass', loaded, mp.loaded_mass_kg);
const cg=(dry.first_moment_kg_m+motor.first_moment_kg_m)/loaded;
near('loaded CG', cg, mp.expected_cg_x_from_nose_m);
near('static margin m', cp-cg, mp.static_margin_m);
near('static margin calibers', (cp-cg)/f.reference_condition.reference_diameter_m, mp.static_margin_calibers);
